"""Generates compat/GSTextureReplacementLoaders.cpp from PCSX2's pcsx2/GS/Renderers/HW/GSTextureReplacementLoaders.cpp
with the libpng handlers (PNGFileReader, PNGLoader, SavePNGImage) replaced by compat/PngLoader.inl: the Windows Imaging
Component on Windows (compat/PngWic.inl, so the Windows build needs no libpng), PCSX2's own libpng handlers elsewhere
(written to compat/PngLibpng.inl). The DDS loader stays as it is.
usage: python make_loaders.py <PCSX2 source dir>"""
import pathlib
import sys

src = pathlib.Path(sys.argv[1]) / "pcsx2/GS/Renderers/HW/GSTextureReplacementLoaders.cpp"
compat = pathlib.Path(__file__).resolve().parent.parent / "compat"
out = compat / "GSTextureReplacementLoaders.cpp"
text = src.read_text(encoding="utf-8")

for include in ("#include <csetjmp>\n", "#include <png.h>\n"):
    assert include in text, include
    text = text.replace(include, "")

start = text.index("static void PNGFileReader(")
dds = text.index("// DDS Handler")
end = text.rindex("////", 0, dds)  # the banner line above "// DDS Handler"
end = text.rindex("\n", 0, end) + 1
libpng = ("// Generated by tools/make_loaders.py: PCSX2's libpng handlers from GSTextureReplacementLoaders.cpp, used outside\n"
          "// Windows (compat/PngLoader.inl). Do not edit; regenerate.\n\n"
          "#include <csetjmp>\n#include <png.h>\n\n" + text[start:end].rstrip() + "\n")
(compat / "PngLibpng.inl").write_text(libpng, encoding="utf-8", newline="\n")
text = text[:start] + '#include "PngLoader.inl"\n\n' + text[end:]

header = ("// Generated by tools/make_loaders.py from PCSX2's GSTextureReplacementLoaders.cpp (PNG through compat/PngLoader.inl:\n"
          "// WIC on Windows, libpng elsewhere). Do not edit; regenerate.\n")
out.write_text(header + text, encoding="utf-8", newline="\n")
print(f"wrote {out}")
